export default async function(self, env, ctx) {
  // monitoring_transactions for section 10, date range
  const filters = [
    {field: "section_id", operator: "eq", value: 10},
    {field: "date", operator: "gte", value: "2030-01-25"},
    {field: "date", operator: "lte", value: "2030-01-30"}
  ];
  let cursor = null;
  let all = [];
  do {
    const p = await env.TROM.read_records("monitoring_transactions", ["id","section_id","gate_id","date"], filters, [{field:"date",direction:"asc"},{field:"id",direction:"asc"}], 500, cursor);
    all.push(...p.records);
    cursor = p.next_cursor;
  } while(cursor);
  console.log("count tx: "+all.length);
  console.log(JSON.stringify(all.slice(0,200), null, 1));
}

